-- Restricted intake RPC. Called only by the authenticated crm-inquiry Edge Function.
create or replace function public.crm_receive_inquiry(payload jsonb) returns uuid language plpgsql security invoker set search_path='' as $$ declare new_id uuid; begin perform pg_advisory_xact_lock(hashtext('crm-intake')); if (select count(*) from public.crm_leads where created_at > now()-interval '1 hour') >= 100 then raise exception 'Intake limit'; end if; if (select count(*) from public.crm_leads where lower(email)=lower(payload->>'email') and created_at > now()-interval '24 hours') >= 5 then raise exception 'Intake limit'; end if; if payload->>'name' is null or payload->>'email' is null or payload->>'description' is null or char_length(payload->>'name') not between 1 and 100 or char_length(payload->>'description') not between 20 and 5000 then raise exception 'Invalid inquiry'; end if; insert into public.crm_leads(name,email,company,website,region,service,budget,description,source,consent_at) values(payload->>'name',payload->>'email',coalesce(payload->>'company',''),coalesce(payload->>'website',''),coalesce(payload->>'region','ROW'),coalesce(payload->>'service',''),coalesce(payload->>'budget',''),payload->>'description','website',now()) returning id into new_id; return new_id; end; $$; revoke all on function public.crm_receive_inquiry(jsonb) from public, anon, authenticated; grant execute on function public.crm_receive_inquiry(jsonb) to service_role; revoke execute on function public.rls_auto_enable() from public, anon, authenticated;
